// Receive TWO SORTED Arrays from Client
// Merge them and send the result back

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define MAX 100

int main() {
	int server_fd, client_fd;
	struct sockaddr_in server_addr, client_addr;
	socklen_t addr_size = sizeof(client_addr);

	int n1, n2;
	int a[MAX], b[MAX], merged[MAX * 2];

	// Creating a SOCKET
	server_fd = socket(AF_INET, SOCK_STREAM, 0);

	// Server address
	server_addr.sin_family = AF_INET;
	server_addr.sin_addr.s_addr = INADDR_ANY;
	server_addr.sin_port = htons(PORT);

	// Bind
	bind(server_fd, (struct sockaddr *)&server_addr,
					sizeof(server_addr));

	// Listen
	listen(server_fd, 5);

	printf("Server waiting for connection...\n");

	// Accept Client
	client_fd = accept(server_fd,
					(struct sockaddr *)&client_addr,
					&addr_size);

	printf("Client Connected!\n");

	// Receive sizes
	recv(client_fd, &n1, sizeof(n1), 0);
	recv(client_fd, &n2, sizeof(n2), 0);

	// Receive arrays
	recv(client_fd, a, n1 * sizeof(int), 0);
	recv(client_fd, b, n2 * sizeof(int), 0);

	// Merge
	int i = 0, j = 0, k = 0;

	while (i < n1 && j < n2) {
		if (a[i] < b[j])
			merged[k++] = a[i++];
		else
			merged[k++] = b[j++];
	}

	while (i < n1)
	merged[k++] = a[i++];

	while (j < n2)
		merged[k++] = b[j++];

	// Send size
	int total = n1 + n2;
	send(client_fd, &total, sizeof(total), 0);

	// Send merged array
	send(client_fd, merged, total * sizeof(int), 0);

	printf("Merged array sent to Client.\n");

	close(client_fd);
	close(server_fd);

	return 0;
}
